NOVA250_PAYLOAD
ACTUAL="$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')"
[[ "$ACTUAL" == "$EXPECTED_ZIP_SHA256" ]] || { echo "ZIP SHA 불일치" >&2; exit 1; }
python3 - "$TMP/$ZIP_NAME" "$TMP" <<'PYEX'
import sys,zipfile
z=zipfile.ZipFile(sys.argv[1]); bad=z.testzip(); assert bad is None,bad; z.extractall(sys.argv[2])
PYEX
ROOT="$TMP/$ROOT_NAME"
[[ -s "$ROOT/app/main.py" && -s "$ROOT/SOURCE_MANIFEST.sha256" ]] || { echo "CLEAN source 누락" >&2; exit 1; }
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null)
python3 - "$ROOT/BUILD_INFO.json" <<'PYBI'
import json,sys
b=json.load(open(sys.argv[1])); assert b.get('version')=='NOVA-2.5.0',b; assert b.get('policy')=='CLEAN_REALTIME_CORE_R1',b
print('BUILD_INFO=PASS')
PYBI

say "3/8 Host 정적검증 — active 컨테이너는 아직 건드리지 않음"
python3 -m py_compile "$ROOT/app/main.py" "$ROOT/app/realtime_core.py" "$ROOT/app/runtime_health.py" "$ROOT/app/evidence_engine.py" "$ROOT/app/archive_engine.py" "$ROOT/app/shadow_engine.py" "$ROOT/app/rs_shadow_engine.py" "$ROOT/scripts/replay_backtest.py" "$ROOT/scripts/realtime_loadtest.py" "$ROOT/scripts/selfcheck.py"
node --check "$ROOT/static/nova.js"
grep -Fq "APP_VERSION='NOVA-2.5.0'" "$ROOT/app/main.py"
grep -Fq "@app.get('/api/livez')" "$ROOT/app/main.py"
grep -Fq "@app.get('/api/opening-profit-bridge')" "$ROOT/app/main.py"
echo "STATIC_GATE=PASS"

say "4/8 Docker build — image 내부 selfcheck + sustained/burst loadtest"
sudo docker build --pull -t "$IMAGE" "$ROOT"
sudo docker network inspect "$NETWORK" >/dev/null 2>&1 || sudo docker network create "$NETWORK" >/dev/null

say "5/8 Shadow Candidate — 외부 market task OFF, 별도 포트/임시 data"
CAND_PORT="$(python3 - <<'PYPORT'
import socket
s=socket.socket();s.bind(('127.0.0.1',0));print(s.getsockname()[1]);s.close()
PYPORT
)"
mkdir -p "$TMP/candidate-data"; chmod 700 "$TMP/candidate-data"
sudo docker run -d --name "$CANDIDATE" --network "$NETWORK" --env-file "$APP_DIR/.env" \
  -e PORT=8000 -e NOVA_DATA_DIR=/app/data -e NOVA_CANDIDATE_MODE=1 \
  -v "$TMP/candidate-data:/app/data" -p "127.0.0.1:${CAND_PORT}:8000" "$IMAGE" >/dev/null
CAND_OK=0
for i in $(seq 1 80); do
  J="$(curl -fsS --connect-timeout 1 --max-time 2 "http://127.0.0.1:${CAND_PORT}/api/livez" 2>/dev/null || true)"
  if [[ -n "$J" ]] && printf '%s' "$J" | python3 -c 'import sys,json;j=json.load(sys.stdin);raise SystemExit(0 if j.get("ok") and j.get("version")=="NOVA-2.5.0" and j.get("candidate_mode") is True and j.get("realtime_running") else 1)' 2>/dev/null; then CAND_OK=1;break;fi
  sleep .25
done
[[ $CAND_OK -eq 1 ]] || { sudo docker logs --tail 250 "$CANDIDATE" || true; echo "candidate livez 실패" >&2; exit 1; }
RH="$(curl -fsS --max-time 2 "http://127.0.0.1:${CAND_PORT}/api/realtime-health")"
printf '%s' "$RH" | python3 -c 'import sys,json;j=json.load(sys.stdin);assert j.get("ok") is True;assert not (j.get("faults") or []);print("CANDIDATE_RT_HEALTH=PASS")'
for i in $(seq 1 30); do
  T="$(curl -fsS -o /dev/null -w '%{time_total}' --connect-timeout 1 --max-time 1.5 "http://127.0.0.1:${CAND_PORT}/api/livez")" || { echo "candidate soak fail $i" >&2; exit 1; }
  python3 - "$T" <<'PYT'
import sys
assert float(sys.argv[1]) < 0.75,sys.argv[1]
PYT
  sleep .10
done
echo "CANDIDATE_SOAK=PASS"
sudo docker rm -f "$CANDIDATE" >/dev/null

say "6/8 Atomic cutover — 이 시점부터만 active 교체"
# Back up public static before any sync.
if [[ -d "$GUARD_STATIC" ]]; then
  mkdir -p "$GUARD_BK"
  [[ -f "$GUARD_STATIC/index.html" ]] && sudo cp "$GUARD_STATIC/index.html" "$GUARD_BK/index.html" || true
  [[ -f "$GUARD_STATIC/nova.js" ]] && sudo cp "$GUARD_STATIC/nova.js" "$GUARD_BK/nova.js" || true
fi
CUTOVER=1
sudo docker rm -f "$BACKUP" >/dev/null 2>&1 || true
sudo docker stop -t 15 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
sudo docker rename "$CONTAINER" "$BACKUP"; OLD_RENAMED=1

run_final() {
sudo docker run -d \
  --name "$CONTAINER" \
  --restart unless-stopped \
  --log-driver json-file \
  --log-opt max-size=10m \
  --log-opt max-file=3 \
  --network "$NETWORK" \
  --env-file "$APP_DIR/.env" \
  -e NOVA_DATA_DIR=/app/data \
  -e NOVA_DISCOVERY_SECONDS=8 \
  -e NOVA_NXT_AFTER_DISCOVERY_SECONDS=5 \
  -e NOVA_NXT_EARLY_MAX_RATE=5.0 \
  -e NOVA_NXT_PRE_MAX_RATE=7.5 \
  -e NOVA_NXT_IGNITION_MAX_RATE=9.5 \
  -e NOVA_NXT_LATE_RATE=10.0 \
  -e NOVA_NXT_ALERT_COOLDOWN=180 \
  -e NOVA_NXT_RADAR_TOP=30 \
  -e NOVA_NXT_FASTEST_DISCOVERY_SECONDS=3 \
  -e NOVA_NXT_PREMARKET_DISCOVERY_SECONDS=4 \
  -e NOVA_NXT_ALLDAY_DISCOVERY_SECONDS=5 \
  -e NOVA_SMART_CLOSE_KRX_BACKFILL_MAX_CODES=80 \
  -e NOVA_SMART_CLOSE_KRX_BACKFILL_RETRY_SECONDS=180 \
  -e NOVA_NXT_FAST_REST_TIMEOUT=2.7 \
  -e NOVA_NXT_SLOW_CONTEXT_SECONDS=15 \
  -e NOVA_NXT_ALLDAY_INTEGRATED_EVERY=2 \
  -e NOVA_NXT_BURST_WATCH_LIMIT=20 \
  -e NOVA_NXT_BURST_HIGHRES_LIMIT=8 \
